using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
namespace StudentAge.Sanguosha {
 public sealed class Seat {
  public General General;public int Hp,MaxHp,Nightmare;public bool FaceDown,Luoyi,UsedSlash,Drunk;public int Slashes,Rende,Wines;
  public readonly List<Card> Hand=new List<Card>(),Judgments=new List<Card>(),Buqu=new List<Card>();public readonly Card[] Equipment=new Card[4];public readonly HashSet<string> Used=new HashSet<string>();
  public bool Has(string skill)=>General.Has(skill);public IEnumerable<Card> Cards=>Hand.Concat(Equipment.Where(c=>c!=null));public string Weapon=>Equipment[0]?.Kind;public string Armor=>Equipment[1]?.Kind;
  public int Range=>Catalog.Range(Weapon);public bool Wounded=>Hp<MaxHp;
 }
 public sealed class Option {public string Label,UseKind;public int CardId=-1,Score,Target=-1;internal IEnumerator Action;public Option(string label,int score=0,int card=-1,IEnumerator action=null){Label=label;Score=score;CardId=card;Action=action;}}
 public sealed class Prompt {public DecisionKind Kind;public Card Subject;public string SubjectKind;public int Actor;public string Text;public List<Option> Options;public List<Card> Reveal;public Prompt(int actor,string text,IEnumerable<Option> options,IEnumerable<Card> reveal=null){Actor=actor;Text=text;Options=options.ToList();Reveal=reveal?.ToList();if(Options.Count==0)throw new InvalidOperationException("Empty decision: "+text);}}
 public sealed class MatchEvent {public int Sequence,Actor,Target,DrawCount,EquipmentSlot=-1;public string Movement;public string Text,Sound,JudgmentReason,JudgmentStage;public bool JudgmentSuccess;public Card Card;}
 // Rules run as a suspended iterator stack. A response never consumes a frame or re-enters a phase.
 // Unity, the AI and tests all submit the same validated prompt choice.
 public sealed class Match {
  public readonly Seat[] Seats=new Seat[2];public readonly List<Card> DrawPile,Discard=new List<Card>();public readonly List<string> Log=new List<string>();public readonly List<MatchEvent> Events=new List<MatchEvent>();
  public int DefeatedActor{get;private set;}=-1;public int DefeatSource{get;private set;}=-1;public bool Surrendered{get;private set;}
  public readonly bool Easy;public int Turn{get;private set;}public int TurnNumber{get;private set;}public int Winner{get;private set;}=-2;public Prompt Pending{get;private set;}public string Phase{get;private set;}="准备";
  readonly Random random;readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();int answer,serial;Card selected,judged;bool responded,cancelled;readonly HashSet<int> resolving=new HashSet<int>();
  public Match(string player,string opponent,bool easy,int seed){Easy=easy;random=new Random(seed);for(int i=0;i<2;i++){var g=Catalog.Get(i==0?player:opponent);Seats[i]=new Seat{General=g,Hp=g.Hp+(easy?1:0),MaxHp=g.Hp+(easy?1:0)};}DrawPile=Deck.CreateDuel();Shuffle(DrawPile);stack.Push(Run());Pump();}
  public void Choose(int index){if(Pending==null||index<0||index>=Pending.Options.Count)throw new ArgumentOutOfRangeException(nameof(index));answer=index;Pending=null;Pump();}
  public int AiChoice(){if(Pending==null)throw new InvalidOperationException();int best=Pending.Options.Max(o=>o.Score);var choices=Pending.Options.Select((v,i)=>new{v,i}).Where(x=>x.v.Score==best).ToArray();return choices[random.Next(choices.Length)].i;}
  public void Surrender(int actor){if(Winner!=-2)return;Surrendered=true;Winner=1-actor;Pending=null;stack.Clear();Say(actor,1-actor,"认输");}
  void Pump(){int guard=0;while(stack.Count>0&&Winner==-2){if(++guard>10000)throw new InvalidOperationException("Rules loop did not yield");var top=stack.Peek();if(!top.MoveNext()){stack.Pop();continue;}if(top.Current is Prompt p){Pending=p;return;}if(top.Current is IEnumerator e)stack.Push(e);}if(Winner!=-2){Pending=null;stack.Clear();}}
  void Shuffle(List<Card> cards){for(int i=cards.Count-1;i>0;i--){int j=random.Next(i+1);var c=cards[i];cards[i]=cards[j];cards[j]=c;}}
  public void Say(int actor,int target,string text,string sound=null,Card card=null){Log.Add(text);if(Log.Count>70)Log.RemoveAt(0);Events.Add(new MatchEvent{Sequence=++serial,Actor=actor,Target=target,Text=text,Sound=sound,Card=card});if(Events.Count>120)Events.RemoveAt(0);}
  string Name(int a)=>Seats[a].General.Name;Suit SuitOf(int a,Card c)=>Seats[a].Has("hongyan")&&c.Suit==Suit.Spade?Suit.Heart:c.Suit;bool Red(int a,Card c)=>SuitOf(a,c)==Suit.Heart||SuitOf(a,c)==Suit.Diamond;
  string KindOf(int a,Card c)=>Seats[a].Hand.Contains(c)&&Seats[a].Has("wushen")&&SuitOf(a,c)==Suit.Heart?"slash":c.Kind;
  public int Distance(int a,int b)=>Math.Max(1,1+(Seats[b].Equipment[2]!=null?1:0)-(Seats[a].Equipment[3]!=null?1:0)-(Seats[a].Has("mashu")?1:0));
  Card Top(){if(DrawPile.Count==0){var recyclable=Discard.Where(c=>!resolving.Contains(c.Id)).ToArray();if(recyclable.Length==0)return null;Discard.RemoveAll(c=>!resolving.Contains(c.Id));DrawPile.AddRange(recyclable.Select(c=>c.Physical));Shuffle(DrawPile);Say(-1,-1,"牌堆已空，洗回"+recyclable.Length+"张弃牌");}var c=DrawPile[0];DrawPile.RemoveAt(0);return c;}
  void Draw(int a,int n){int drawn=0;for(int i=0;i<n;i++){var c=Top();if(c==null)break;Seats[a].Hand.Add(c);drawn++;}Say(a,a,Name(a)+"摸"+drawn+"张牌","choose-item");Events[Events.Count-1].DrawCount=drawn;}
  int Value(int a,Card c){string k=KindOf(a,c);return k=="peach"?(Seats[a].Wounded?10:7):k=="jink"?7:k=="nullification"?7:k=="ex_nihilo"?10:k=="slash"?5:c.Equip?4:6;}
  IEnumerator Yes(int a,string text,int score=5){yield return new Prompt(a,text,new[]{new Option("发动",score),new Option("取消",0)});if(answer==0){var skill=Seats[a].General.Skills.Split(' ').FirstOrDefault(key=>text.StartsWith(Catalog.SkillName(key)+"："));if(skill!=null)Say(a,a,Name(a)+"发动"+Catalog.SkillName(skill),skill);else if(text.StartsWith("八卦阵："))Say(a,a,"八卦阵发动","armor");else if(Seats[a].Weapon!=null&&text.StartsWith(Catalog.CardName(Seats[a].Weapon)+"："))Say(a,a,Catalog.CardName(Seats[a].Weapon)+"发动","weapon");}}
  IEnumerator Pick(int a,string text,IEnumerable<Card> cards,bool optional=false,bool publicFaces=true,bool wantGood=false){var list=cards.ToList();selected=null;if(list.Count==0)yield break;bool skillDrag=text.Contains("：")&&list.All(c=>Seats[a].Cards.Contains(c));int target=text.StartsWith("仁德")?1-a:-1;var choices=list.Select(c=>new Option(c.Text,wantGood?Value(a,c):10-Value(a,c),c.Id){Target=target}).ToList();if(optional)choices.Add(new Option("取消",-1));yield return new Prompt(a,text,choices,publicFaces?list:null){Kind=skillDrag?DecisionKind.SkillCard:DecisionKind.Choice};selected=answer<list.Count?list[answer]:null;}
  IEnumerator Lose(int a,Card c,bool discard=true){if(c==null)yield break;var p=Seats[a];bool hand=p.Hand.Remove(c),equip=false;int slot=Array.IndexOf(p.Equipment,c);if(slot>=0){p.Equipment[slot]=null;equip=true;}p.Judgments.Remove(c);if(discard&&!Discard.Contains(c))Discard.Add(c.Physical);if(discard&&!resolving.Contains(c.Id))MoveCard(a,-1,c,"discard",slot);
   if(hand&&p.Hand.Count==0&&p.Has("lianying")){yield return Yes(a,"连营：摸一张牌");if(answer==0)Draw(a,1);}if(equip&&p.Has("xiaoji")){yield return Yes(a,"枭姬：摸两张牌");if(answer==0)Draw(a,2);}}
  void MoveCard(int from,int to,Card c,string movement,int slot){Say(from,to,Name(from)+(movement=="discard"?"弃置 ":"失去 ")+c.Text,"card-place",c.Physical);var ev=Events[Events.Count-1];ev.Movement=movement;ev.EquipmentSlot=slot;}
  IEnumerator Recover(int a,int n){var p=Seats[a];int old=p.Hp;p.Hp=Math.Min(p.MaxHp,p.Hp+n);int removed=Math.Max(0,p.Buqu.Count-Math.Max(0,1-p.Hp));while(removed-->0){yield return Pick(a,"不屈：移去一张不屈牌",p.Buqu);p.Buqu.Remove(selected);Discard.Add(selected.Physical);}if(p.Hp>old)Say(a,a,Name(a)+"回复"+(p.Hp-old)+"点体力","recover");}
  void ShowJudgment(int a,string reason,Card card,string stage,bool good=false){
   bool harmful=reason=="乐不思蜀"||reason=="兵粮寸断"||reason=="闪电"||reason=="雷击"||reason=="刚烈"||reason=="武魂";
   bool success=card!=null&&(harmful?!good:good);
   string result=reason=="乐不思蜀"?(good?"正常出牌":"跳过出牌阶段"):reason=="兵粮寸断"?(good?"正常摸牌":"跳过摸牌阶段"):reason=="八卦阵"?(good?"视为打出闪":"未产生闪"):good?"有利判定":"不利判定";
   Say(a,a,reason+" · "+(card==null?"无可用判定牌":card.Text)+(stage=="result"?" · "+(success?"判定成功":"判定失败")+" · "+result:stage=="replace"?" · 改判":" · 判定中"),"judgment-"+stage,card);
   var ev=Events[Events.Count-1];ev.JudgmentReason=reason;ev.JudgmentStage=stage;ev.JudgmentSuccess=success;
  }
  IEnumerator Judge(int a,string reason,Func<Card,bool> good){judged=Top();if(judged==null){ShowJudgment(a,reason,null,"result");yield break;}Card current=judged;ShowJudgment(a,reason,current,"reveal");
   for(int k=0;k<2;k++){int b=(Turn+k)%2;var p=Seats[b];bool own=b==a;var eligible=p.Has("guicai")?p.Hand.ToList():p.Has("guidao")?p.Cards.Where(c=>!Red(b,c)).ToList():new List<Card>();if(eligible.Count==0)continue;
    var opts=new List<Option>{new Option("不改判",0)};opts.AddRange(eligible.Select(c=>new Option(c.Text,(good(c)==own?12:-12)-Value(b,c),c.Id){UseKind=p.Has("guidao")?"guidao":"guicai"}));
    yield return new Prompt(b,Catalog.SkillName(p.Has("guidao")?"guidao":"guicai")+"：将合法牌拖到判定区域，或不改判",opts){Kind=DecisionKind.Judgment,Subject=current,SubjectKind=reason};
    if(answer>0){Card repl=eligible[answer-1];yield return Lose(b,repl,false);if(p.Has("guidao"))p.Hand.Add(current.Physical);else Discard.Add(current.Physical);current=repl;Say(b,a,Name(b)+"发动"+(p.Has("guidao")?"鬼道":"鬼才"),p.Has("guidao")?"guidao":"guicai");ShowJudgment(a,reason,current,"replace");}}
   judged=current;ShowJudgment(a,reason,current,"result",good(current));
  }
  IEnumerator DisposeJudge(int a,Card c,bool obtained=false){if(c==null||obtained)yield break;if(Seats[a].Has("tiandu")){yield return Yes(a,"天妒：获得判定牌 "+c.Text);if(answer==0){Seats[a].Hand.Add(c);yield break;}}Discard.Add(c.Physical);}
  IEnumerator Run(){Draw(0,4);Draw(1,4);while(Winner==-2){TurnNumber++;if(TurnNumber>600){Winner=-1;Say(-1,-1,"牌局达到600回合，和局");yield break;}yield return Round(Turn);Turn=1-Turn;}}
  IEnumerator Round(int a){var p=Seats[a];int b=1-a;Phase="准备阶段";Say(a,a,"—— "+Name(a)+"的回合 ——");p.Slashes=0;p.Rende=0;p.Used.Clear();p.Luoyi=p.UsedSlash=p.Drunk=false;p.Wines=0;if(p.FaceDown){p.FaceDown=false;Say(a,a,Name(a)+"翻回正面，跳过本回合");yield break;}
   if(p.Has("guanxing")){yield return Yes(a,"观星：观看牌堆顶两张牌");if(answer==0){var peek=new List<Card>();for(int i=0;i<2;i++){var c=Top();if(c!=null)peek.Add(c);}var top=new List<Card>();while(peek.Count>0){yield return Pick(a,"观星：选择下一张牌（先选的靠近牌堆顶）",peek,false,true,true);var c=selected;peek.Remove(c);yield return new Prompt(a,c.Text+"放到哪里？",new[]{new Option("牌堆顶",Value(a,c)),new Option("牌堆底",5)},new[]{c});if(answer==0)top.Add(c);else DrawPile.Add(c.Physical);}DrawPile.InsertRange(0,top);}}
   if(p.Has("luoshen")){for(int i=0;i<108;i++){yield return Yes(a,"洛神：继续判定，黑色牌收入手牌");if(answer!=0)break;yield return Judge(a,"洛神",c=>!Red(a,c));var c=judged;bool black=c!=null&&!Red(a,c);if(black)p.Hand.Add(c.Physical);yield return DisposeJudge(a,c,black);if(!black)break;}}
   bool fast=false;if(p.Has("shensu")&&Targetable(a,b,"slash")){yield return Yes(a,"神速：跳过判定和摸牌，使用一张杀",p.Judgments.Count>0?12:-2);fast=answer==0;if(fast)yield return Slash(a,b,null,true);}
   bool skip=false,skipDraw=false;if(!fast){Phase="判定阶段";foreach(var delayed in p.Judgments.ToArray().Reverse()){p.Judgments.Remove(delayed);yield return Nullify(a,delayed.Kind,false,delayed);bool nullified=cancelled;if(!nullified){if(delayed.Kind=="indulgence"){yield return Judge(a,"乐不思蜀",c=>SuitOf(a,c)==Suit.Heart);var c=judged;skip|=c!=null&&SuitOf(a,c)!=Suit.Heart;yield return DisposeJudge(a,c);Discard.Add(delayed.Physical);}else if(delayed.Kind=="supply_shortage"){yield return Judge(a,"兵粮寸断",c=>SuitOf(a,c)==Suit.Club);var c=judged;skipDraw|=c!=null&&SuitOf(a,c)!=Suit.Club;yield return DisposeJudge(a,c);Discard.Add(delayed.Physical);}else{yield return Judge(a,"闪电",c=>!(SuitOf(a,c)==Suit.Spade&&c.Rank>=2&&c.Rank<=9));var c=judged;bool hit=c!=null&&SuitOf(a,c)==Suit.Spade&&c.Rank>=2&&c.Rank<=9;yield return DisposeJudge(a,c);if(hit){Discard.Add(delayed.Physical);yield return Damage(-1,a,3,delayed,"lightning");}else if(!Seats[b].Judgments.Any(x=>x.Kind=="lightning"))Seats[b].Judgments.Add(delayed);else Discard.Add(delayed.Physical);}}else if(delayed.Kind=="lightning"&&!Seats[b].Judgments.Any(x=>x.Kind=="lightning"))Seats[b].Judgments.Add(delayed);else Discard.Add(delayed.Physical);}
    if(!skipDraw){Phase="摸牌阶段";bool replaced=false;if(p.Has("shelie")){yield return Yes(a,"涉猎：改为亮出五张牌，每种花色获得一张",9);if(answer==0){replaced=true;var cards=new List<Card>();for(int i=0;i<5;i++){var c=Top();if(c!=null)cards.Add(c);}while(cards.Count>0){yield return Pick(a,"涉猎：每种花色取一张",cards,false,true,true);Card c=selected;p.Hand.Add(c.Physical);cards.Remove(c);var rest=cards.Where(x=>SuitOf(a,x)==SuitOf(a,c)).ToArray();foreach(var r in rest){cards.Remove(r);Discard.Add(r.Physical);}}}}
    if(p.Has("tuxi")&&Seats[b].Hand.Count>0){yield return Yes(a,"突袭：放弃摸牌，获得对手一张手牌",Seats[b].Hand.Count<=2?10:2);if(answer==0){replaced=true;Card c=Seats[b].Hand[random.Next(Seats[b].Hand.Count)];yield return Lose(b,c,false);p.Hand.Add(c.Physical);}}
    if(!replaced){int n=Easy?3:2;if(p.Has("yingzi")){yield return Yes(a,"英姿：额外摸一张牌");if(answer==0)n++;}if(p.Has("luoyi")){yield return Yes(a,"裸衣：少摸一张，本回合杀与决斗伤害+1",p.Hand.Count(c=>KindOf(a,c)=="slash"||KindOf(a,c)=="duel")>0?8:-2);if(answer==0){n--;p.Luoyi=true;}}Draw(a,n);}}}
   if(p.Has("shensu")&&p.Cards.Any(c=>c.Equip)&&Targetable(a,b,"slash")){yield return Yes(a,"神速：弃一张装备牌，跳过出牌阶段并出杀",skip?10:-5);if(answer==0){yield return Pick(a,"神速：弃置装备牌",p.Cards.Where(c=>c.Equip));yield return Lose(a,selected);skip=true;yield return Slash(a,b,null,true);}}
   Phase="出牌阶段";if(!skip){while(Winner==-2){var options=PlayOptions(a);options.Add(new Option("结束出牌",0));var prompt=new Prompt(a,Name(a)+" · 出牌阶段",options){Kind=DecisionKind.Play};yield return prompt;var chosen=prompt.Options[answer];if(chosen.Action==null)break;yield return chosen.Action;}}
   Phase="弃牌阶段";if(p.Has("keji")&&!p.UsedSlash&&p.Hand.Count>Math.Max(0,p.Hp))Say(a,a,"克己：跳过弃牌阶段","keji");if(!(p.Has("keji")&&!p.UsedSlash)){int max=Math.Max(0,p.Hp);while(p.Hand.Count>max){yield return Pick(a,"弃牌至"+max+"张（还需弃"+(p.Hand.Count-max)+"张）",p.Hand);yield return Lose(a,selected);}}
   Phase="结束阶段";if(p.Has("biyue")){yield return Yes(a,"闭月：摸一张牌");if(answer==0)Draw(a,1);}if(p.Has("jushou")){yield return Yes(a,"据守：摸三张牌并翻面",p.Hp<=2&&p.Hand.Count<2?6:-3);if(answer==0){Draw(a,3);p.FaceDown=true;}}p.Luoyi=p.Drunk=false;
  }
  bool Targetable(int a,int b,string kind){var p=Seats[b];if((kind=="slash"||kind=="duel")&&p.Has("kongcheng")&&p.Hand.Count==0)return false;if((kind=="snatch"||kind=="indulgence")&&p.Has("qianxun"))return false;return true;}
  bool CanSlash(int a)=>Seats[a].Has("paoxiao")||Seats[a].Weapon=="crossbow"||Seats[a].Slashes<(Easy?2:1);
  bool InRange(int a,int b,Card c=null)=>Distance(a,b)+(c!=null&&c==Seats[a].Equipment[3]?1:0)<=(c!=null&&c==Seats[a].Equipment[0]?1:Seats[a].Range)||(c!=null&&Seats[a].Has("wushen")&&SuitOf(a,c)==Suit.Heart);
  bool Legal(int a,string k,Card c){int b=1-a;var p=Seats[a];var q=Seats[b];if(k=="jink"||k=="nullification")return false;if(k=="slash")return CanSlash(a)&&Targetable(a,b,k)&&InRange(a,b,c);if(k=="peach")return p.Wounded;if(k=="wine")return p.Wines<1;if(Catalog.Slot(k)>=0)return true;if(!Targetable(a,b,k))return false;if(k=="snatch")return q.Cards.Any()||q.Judgments.Count>0?(p.Has("qicai")||Distance(a,b)<=1):false;if(k=="dismantlement")return q.Cards.Any()||q.Judgments.Count>0;if(k=="collateral")return q.Weapon!=null&&Targetable(b,a,"slash")&&InRange(b,a);if(k=="supply_shortage")return !q.Judgments.Any(x=>x.Kind==k)&&(p.Has("qicai")||Distance(a,b)<=1);if(k=="indulgence")return !q.Judgments.Any(x=>x.Kind==k);if(k=="lightning")return !p.Judgments.Any(x=>x.Kind==k);return true;}
  List<Option> PlayOptions(int a){var p=Seats[a];var opts=new List<Option>();foreach(var c in p.Hand.ToArray()){string k=KindOf(a,c);if(Legal(a,k,c))opts.Add(new Option(c.Text,PlayScore(a,k,c),c.Id,Use(a,c,k)){UseKind=k,Target=TableTarget(a,k)});foreach(string v in Converted(a,c,false)){if(v!=k&&Legal(a,v,c))opts.Add(new Option(c.Text+" → "+Catalog.CardName(v),PlayScore(a,v,c)-1,c.Id,Use(a,c,v)){UseKind=v,Target=TableTarget(a,v)});}}
   foreach(var c in p.Equipment.Where(c=>c!=null).ToArray())foreach(string k in Converted(a,c,false))if(Legal(a,k,c))opts.Add(new Option(c.Text+" → "+Catalog.CardName(k),PlayScore(a,k,c)-2,c.Id,Use(a,c,k)){UseKind=k,Target=TableTarget(a,k)});
   foreach(string skill in new[]{"zhiheng","kurou","rende","qingnang","jieyin","fanjian","gongxin"}){bool enabled=p.Has(skill)&&(!p.Used.Contains(skill)||skill=="kurou"||skill=="rende");if(skill=="zhiheng")enabled&=p.Cards.Any();if(skill=="kurou")enabled&=p.Hp>0;if(skill=="rende"||skill=="qingnang"||skill=="fanjian")enabled&=p.Hand.Count>0;if(skill=="qingnang")enabled&=p.Wounded||Seats[1-a].Wounded;if(skill=="jieyin")enabled&=p.Hand.Count>=2&&!Seats[1-a].General.Female&&Seats[1-a].Wounded;if(skill=="gongxin")enabled&=Seats[1-a].Hand.Count>0;if(enabled)opts.Add(new Option(SkillName(skill),SkillScore(a,skill),-1,Active(a,skill)));}
   if(p.Weapon=="spear"&&p.Hand.Count>=2&&CanSlash(a)&&Targetable(a,1-a,"slash")&&InRange(a,1-a))opts.Add(new Option("丈八蛇矛：两张手牌当杀",p.Hand.Any(c=>KindOf(a,c)=="slash")?-2:4,-1,Spear(a)));
   if(p.Has("guhuo")&&p.Hand.Count>0)foreach(string k in new[]{"slash","peach","ex_nihilo","duel","dismantlement","snatch","savage_assault","archery_attack","drowning"})if(Legal(a,k,null))opts.Add(new Option("蛊惑 · "+Catalog.CardName(k),p.Hand.Any(c=>KindOf(a,c)==k)?3:-2,-1,BluffUse(a,k)));
   return opts;
  }
  static int TableTarget(int a,string kind)=>new[]{"slash","duel","snatch","dismantlement","collateral","indulgence","supply_shortage","drowning"}.Contains(kind)?1-a:Catalog.Slot(kind)>=0||kind=="peach"||kind=="wine"||kind=="ex_nihilo"||kind=="lightning"?a:-1;
  int PlayScore(int a,string k,Card c){var p=Seats[a];if(k=="peach")return 20;if(k=="wine")return CanSlash(a)&&p.Hand.Any(x=>KindOf(a,x)=="slash")?9:-3;if(k=="ex_nihilo")return 18;if(k=="slash"||k=="duel")return 8;if(k=="lightning")return -3;if(k=="god_salvation")return p.Wounded&&!Seats[1-a].Wounded?8:-2;if(k=="amazing_grace")return 2;if(c!=null&&c.Equip){var old=p.Equipment[c.Slot];return old==null?11:old.Kind==c.Kind?-3:Catalog.Range(c.Kind)>Catalog.Range(old.Kind)?6:-1;}return 7;}
  int SkillScore(int a,string k){var p=Seats[a];if(k=="kurou")return p.Hp>=3&&p.Hand.Count<4?5:-4;if(k=="rende")return p.Wounded&&p.Rende<2&&p.Hand.Count>=2-p.Rende?3:-6;if(k=="qingnang")return p.Wounded?9:-6;if(k=="jieyin")return p.Wounded?4:-5;if(k=="zhiheng")return 1;return 7;}
  static string SkillName(string k){string[] keys={"zhiheng","kurou","rende","qingnang","jieyin","fanjian","gongxin"},v={"制衡","苦肉","仁德","青囊","结姻","反间","攻心"};return v[Array.IndexOf(keys,k)];}
  IEnumerable<string> Converted(int a,Card c,bool response){var p=Seats[a];if(p.Has("wushen")&&p.Hand.Contains(c)&&SuitOf(a,c)==Suit.Heart)yield break;if(p.Has("longdan")&&p.Hand.Contains(c)){if(c.Kind=="slash")yield return "jink";if(c.Kind=="jink")yield return "slash";}if(p.Has("wusheng")&&Red(a,c))yield return "slash";if(p.Has("qingguo")&&p.Hand.Contains(c)&&!Red(a,c))yield return "jink";if(p.Has("jijiu")&&Turn!=a&&Red(a,c))yield return "peach";if(!response){if(p.Has("qixi")&&!Red(a,c))yield return "dismantlement";if(p.Has("guose")&&SuitOf(a,c)==Suit.Diamond)yield return "indulgence";}}
  // Emit only when a committed card actually uses a conversion; option enumeration stays silent.
  void ConversionVoice(int a,Card c,string kind){var p=Seats[a];string skill=null;
