    else if(kind=="slash"&&p.Has("wusheng"))skill="wusheng";else if(kind=="jink"&&p.Has("qingguo"))skill="qingguo";else if(kind=="peach"&&p.Has("jijiu"))skill="jijiu";else if(kind=="dismantlement"&&p.Has("qixi"))skill="qixi";else if(kind=="indulgence"&&p.Has("guose"))skill="guose";}
