  IEnumerator Nullify(int target,string trick,bool beneficial=false,Card subject=null,int source=-1){Card current=subject;string currentKind=trick;int lastActor=source>=0?source:1-target;var counters=new List<Card>();bool negated=false;int passes=0,a=target;while(passes<2){var p=Seats[a];var cards=p.Hand.Where(c=>KindOf(a,c)=="nullification").ToList();bool bluff=p.Has("guhuo")&&p.Hand.Count>0;if(a!=lastActor&&(cards.Count>0||bluff)){bool wants=((a==target)!=negated)!=beneficial;var opts=new List<Option>{new Option("不使用",0)};opts.AddRange(cards.Select(c=>new Option(c.Text,wants?7:-8,c.Id){UseKind="nullification"}));if(bluff)opts.Add(new Option("蛊惑 · 无懈可击",wants&&p.Hand.Any(c=>c.Kind=="nullification")?5:-3,-3));yield return new Prompt(a,Catalog.CardName(trick)+(negated?"已被无懈，是否反无懈？":"：是否使用无懈可击？"),opts){Kind=DecisionKind.Nullification,Subject=current,SubjectKind=currentKind};if(answer>0){bool success=true;if(opts[answer].CardId==-3){yield return Bluff(a,"nullification");success=responded;if(selected!=null){counters.Add(selected);if(success)current=selected;}}else{var c=cards[answer-1];current=c;counters.Add(c);resolving.Add(c.Id);yield return Lose(a,c);Say(a,target,Name(a)+"使用无懈可击","nullification",c);if(p.Has("jizhi")){yield return Yes(a,"集智：摸一张牌");if(answer==0)Draw(a,1);}}if(success){lastActor=a;currentKind="nullification";negated=!negated;passes=0;}else passes++;}else passes++;}else passes++;a=1-a;}foreach(var counter in counters)resolving.Remove(counter.Id);cancelled=negated;}
  IEnumerator Use(int a,Card c,string kind,bool alreadyLost=false){int b=1-a;var p=Seats[a];if(kind=="slash"){if(p.Slashes>=(Easy?2:1))Say(a,a,Name(a)+"继续出杀",p.Has("paoxiao")?"paoxiao":"weapon");p.Slashes++;p.UsedSlash=true;}if(c!=null)resolving.Add(c.Id);if(c!=null&&!alreadyLost){ConversionVoice(a,c,kind);yield return Lose(a,c);}Say(a,TableTarget(a,kind),Name(a)+"使用"+Catalog.CardName(kind),kind,c);
