  IEnumerator Drowning(int a,int b,Card card){var equipped=Seats[b].Equipment.Where(c=>c!=null).ToArray();if(equipped.Length>0){yield return new Prompt(b,"水淹七军：弃置全部装备，或受到1点伤害",new[]{new Option("弃置全部装备",Seats[b].Hp<=1?20:equipped.Length==1?5:0),new Option("受到1点伤害",3)});if(answer==0){foreach(var c in equipped)yield return Lose(b,c);yield break;}}yield return Damage(a,b,1,card,"drowning");}
  IEnumerator Steal(int a,int b,bool destroy,bool includeJudgments){
