  IEnumerator Duel(int a,int b,Card c){foreach(int actor in new[]{a,b})if(Seats[actor].Has("wushuang"))Say(actor,1-actor,"无双：需要两张杀","wushuang");int who=b,other=a;for(int count=0;count<216;count++){int need=Seats[other].Has("wushuang")?2:1;for(int i=0;i<need;i++){yield return Respond(who,"slash",other,false,c);if(!responded){yield return Damage(other,who,1+(Seats[other].Luoyi?1:0),c,"duel");yield break;}}int swap=who;who=other;other=swap;}}
