  IEnumerator Active(int a,string skill){var p=Seats[a];int b=1-a;var q=Seats[b];p.Used.Add(skill);Say(a,b,Name(a)+"发动"+SkillName(skill),skill);
   switch(skill){case "kurou":yield return HpLoss(a,1);if(Winner==-2)Draw(a,2);break;
    case "zhiheng":{var chosen=new List<Card>();while(true){var available=p.Cards.Except(chosen).ToArray();if(available.Length==0)break;var options=available.Select(c=>new Option(c.Text,6-Value(a,c),c.Id)).ToList();options.Add(new Option(chosen.Count==0?"取消":"确定，换"+chosen.Count+"张",0));yield return new Prompt(a,"制衡：选择任意张牌",options,available){Kind=DecisionKind.SkillCard};if(answer==available.Length)break;chosen.Add(available[answer]);}foreach(var c in chosen)yield return Lose(a,c);Draw(a,chosen.Count);break;}
    case "rende":yield return Pick(a,"仁德：交给对手一张手牌",p.Hand);var given=selected;yield return Lose(a,given,false);q.Hand.Add(given.Physical);p.Rende++;if(p.Rende==2)yield return Recover(a,1);break;
    case "qingnang":yield return Pick(a,"青囊：弃一张手牌",p.Hand);yield return Lose(a,selected);var targets=new List<int>();if(p.Wounded)targets.Add(a);if(q.Wounded)targets.Add(b);yield return new Prompt(a,"青囊：选择回复体力的角色",targets.Select(t=>new Option(Name(t),t==a?10:-5)));yield return Recover(targets[answer],1);break;
    case "jieyin":for(int i=0;i<2;i++){yield return Pick(a,"结姻：弃手牌 "+(i+1)+"/2",p.Hand);yield return Lose(a,selected);}yield return Recover(a,1);yield return Recover(b,1);break;
    case "fanjian":yield return new Prompt(b,"反间：猜测将获得的牌的花色",new[]{new Option("黑桃",1),new Option("梅花",1),new Option("红桃",1),new Option("方块",1)});Suit guessed=(Suit)answer;var card=p.Hand[random.Next(p.Hand.Count)];yield return Lose(a,card,false);q.Hand.Add(card.Physical);Say(a,b,"反间揭示 "+card.Text,"fanjian",card);if(SuitOf(b,card)!=guessed)yield return Damage(a,b,1,null,"fanjian");break;
    case "gongxin":var hearts=q.Hand.Where(c=>SuitOf(b,c)==Suit.Heart).ToArray();var choices=hearts.Select(c=>new Option(c.Text,7,c.Id)).ToList();choices.Add(new Option("不处理",0));yield return new Prompt(a,"攻心：查看对手手牌，选择一张红桃",choices,q.Hand);if(answer>=hearts.Length)break;var heart=hearts[answer];yield return new Prompt(a,heart.Text+"：如何处理？",new[]{new Option("弃置",8),new Option("放回牌堆顶",Turn==a?-2:4)});bool toTop=answer==1;yield return Lose(b,heart,!toTop);if(toTop)DrawPile.Insert(0,heart.Physical);break;
   }
  }
 }
}
